CREATE OR REPLACE PROCEDURE idq_production_eks_calculation.srmara_eks_item_constructbafromea_ins()
BEGIN
INSERT INTO idq_production_eks_calculation.stmara_eks_item (itemid, bitflag, employeeid, cr_locationid, itemgrouptypeid, itemno, shortdesc_int, shortdesc_nat, description_int, description_nat, in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, zlegacymeins, zlegacysatnr, zlegacypmata, zactive, zernam, zaenam, zmtart, zmatkl, zbismt, zmeins, zzeinr, zntgew, ztragr, zspart, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, zinhme, zinhal, zvpreh, zbflme, zisvalidbitflag, zisin_use, zisfood, ziscurrentcontract, znegotiatingcountry, zarticletype, zitem_ba, zsource, constructed, constructedfrom, targetsystem, targetclient)
(SELECT CAST(itemid AS INTEGER) AS itemid, bitflag, CAST(employeeid AS INTEGER) AS employeeid, CAST(cr_locationid AS INTEGER) AS cr_locationid, CAST(itemgrouptypeid AS INTEGER) AS itemgrouptypeid, CAST(itemno AS INTEGER) AS itemno, shortdesc_int, shortdesc_nat, description_int, description_nat, CAST(in_use AS INTEGER) AS in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, zlegacymeins, SUBSTR(CAST(zlegacysatnr AS STRING), 1, 50) AS zlegacysatnr, SUBSTR(CAST(zlegacypmata AS STRING), 1, 50) AS zlegacypmata, CAST(zactive AS INTEGER) AS zactive, zernam, zaenam, zmtart, zmatkl, zbismt, zmeins, zzeinr, CAST(ROUND(CAST(zntgew AS BIGNUMERIC), 0) AS NUMERIC) AS zntgew, ztragr, zspart, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, SUBSTR(CAST(zinhme AS STRING), 1, 3) AS zinhme, zinhal, CAST(zvpreh AS INTEGER) AS zvpreh, zbflme, CAST(zisvalidbitflag AS INTEGER) AS zisvalidbitflag, CAST(zisin_use AS INTEGER) AS zisin_use, CAST(zisfood AS INTEGER) AS zisfood, CAST(ziscurrentcontract AS INTEGER) AS ziscurrentcontract, znegotiatingcountry, zarticletype, CAST(zitem_ba AS INTEGER) AS zitem_ba, zsource, constructed, SUBSTR(CAST(constructedfrom AS STRING), 1, 255) AS constructedfrom, targetsystem, targetclient
    FROM idq_production_eks_calculation.srmara_eks_item_constructbafromea_inssel);
END;
